import path from "node:path";
import type { NextConfig } from "next";

const nextConfig: NextConfig = {
  // pnpm monorepo — tell Next.js where the workspace root is so file
  // tracing can follow symlinks into ../../node_modules/.pnpm/...
  outputFileTracingRoot: path.join(__dirname, "../../"),
  // Bundle the Prisma Linux query engine into the serverless function
  // payload. The binary is generated by `prisma generate` (postinstall)
  // when `binaryTargets` in schema.prisma includes `rhel-openssl-3.0.x`.
  // Without this trace hint, Next.js drops the .so.node file from the
  // function bundle and the dashboard 500s at runtime.
  outputFileTracingIncludes: {
    "/**/*": [
      "../../node_modules/.pnpm/@prisma+client*/node_modules/.prisma/client/libquery_engine-*",
    ],
  },
  images: {
    remotePatterns: [
      {
        protocol: "https",
        hostname: "lh3.googleusercontent.com",
        pathname: "/**",
      },
    ],
  },
  async redirects() {
    return [
      // Phase GTM-01: Brand renamed to Prospect. Operators have `/brands`
      // bookmarks and links out in the wild; 308 (permanent) keeps them
      // working and tells crawlers/clients to update to the new path.
      {
        source: "/brands",
        destination: "/prospects",
        permanent: true,
      },
      {
        source: "/brands/:path*",
        destination: "/prospects/:path*",
        permanent: true,
      },
      // Same rename for the public brand-profile API route. No known
      // consumer references it today (demo apps fetch resolved themes via
      // DemoConfig, D-028), but redirecting costs nothing and protects
      // against an out-of-repo caller.
      {
        source: "/api/brands/:path*",
        destination: "/api/prospects/:path*",
        permanent: true,
      },
    ];
  },
  async headers() {
    return [
      {
        // Apply CORS headers to all API routes
        source: "/api/:path*",
        headers: [
          { key: "Access-Control-Allow-Credentials", value: "true" },
          { key: "Access-Control-Allow-Origin", value: "*" },
          {
            key: "Access-Control-Allow-Methods",
            value: "GET, POST, PUT, PATCH, DELETE, OPTIONS",
          },
          {
            key: "Access-Control-Allow-Headers",
            value:
              "Content-Type, Authorization, x-dynamic-environment-id, X-CSRF-Token, X-Requested-With, Accept, Accept-Version, Content-Length, Content-MD5, Date, X-Api-Version",
          },
        ],
      },
    ];
  },
};

export default nextConfig;
